.promise-list .promise { transition: opacity var(--t-med) var(--ease), transform var(--t-med) var(--ease); opacity: 0.5; padding: var(--s-3) 0 var(--s-4); display: grid; gap: var(--s-2); }
.promise-list .promise.is-active { opacity: 1; }
.promise-list .promise .title { font-size: var(--fs-md); font-weight: var(--fw-medium); display: flex; align-items: center; gap: 0.6rem; }
.promise-list .promise .title::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--accent); flex: none; transition: transform var(--t-med) var(--ease); }
.promise-list .promise.is-active .title::before { transform: scale(1.5); }
.promise-list .promise p { color: var(--on-ink-muted); margin: 0; font-size: var(--fs-sm); }
@media (min-width: 900px) {
  .promise-stage[data-beam="1"] { grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); align-items: stretch; column-gap: var(--s-6); }
  .promise-stage[data-beam="1"] .promise-list { grid-auto-rows: 1fr; gap: 0; }
  .promise-stage[data-beam="1"] .promise { align-content: center; border-top: 1px solid var(--ink-line); padding: var(--s-4) 0; }
  .promise-stage[data-beam="1"] .promise:last-child { border-bottom: 1px solid var(--ink-line); }
  .promise-beam { position: relative; overflow: hidden; border-radius: var(--r-lg); }
  .beam-row { position: absolute; left: 0; right: 0; top: 0; will-change: transform; }
  .beam-line { position: absolute; left: 0; right: 30px; top: 50%; height: 2px; margin-top: -1px;
    background: linear-gradient(90deg, rgba(220, 240, 106, 0) 0%, rgba(220, 240, 106, 0.55) 55%, var(--accent) 100%); }
  .beam-orb { position: absolute; right: 8px; top: 50%; width: 44px; height: 44px; margin-top: -22px; border-radius: 50%;
    background: radial-gradient(circle, #fbffd9 0, var(--accent) 28%, rgba(220, 240, 106, 0) 70%); }
  .beam-sparks { position: absolute; right: 30px; top: 50%; width: 0; height: 0; }
  .beam-sparks i { position: absolute; left: -2px; top: -2px; width: 4px; height: 4px; border-radius: 50%; background: var(--accent); }
}

/* ---- check any address: a light scan sweeps the input bar while a check runs; result rows appear one by one ---- */
.check-form { position: relative; overflow: hidden; }
.check-card.is-busy .check-form::after {
  content: ""; position: absolute; top: 0; bottom: 0; left: 0; width: 30%; pointer-events: none;
  background: linear-gradient(90deg, rgba(220, 240, 106, 0), rgba(220, 240, 106, 0.55), rgba(220, 240, 106, 0));
  animation: scan 1.3s var(--ease-in-out) infinite;
}
@keyframes scan { from { transform: translateX(-100%); } to { transform: translateX(340%); } }
.check-result .findings > li { animation: row-in 0.5s var(--ease) both; }
.check-result .findings > li:nth-child(1) { animation-delay: 0.05s; }
.check-result .findings > li:nth-child(2) { animation-delay: 0.13s; }
.check-result .findings > li:nth-child(3) { animation-delay: 0.21s; }
.check-result .findings > li:nth-child(4) { animation-delay: 0.29s; }
.check-result .findings > li:nth-child(5) { animation-delay: 0.37s; }
.check-result .findings > li:nth-child(n + 6) { animation-delay: 0.45s; }
@keyframes row-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

/* ---- security ticks + lifts on hover ---- */
.sec-tick { width: 1.1rem; height: 1.1rem; color: var(--success); margin-top: 0.2em; }
.sec-tick path { stroke-dasharray: 24; stroke-dashoffset: 24; }
.security-list[data-in="1"] .sec-tick path { animation: draw-tick 0.5s var(--ease) both; animation-delay: calc(var(--i) * 0.14s + 0.1s); }
@keyframes draw-tick { to { stroke-dashoffset: 0; } }
.watch-item, .who-groups li { transition: transform var(--t-med) var(--ease), box-shadow var(--t-med) var(--ease); }
@media (hover: hover) {
  .watch-item:hover { transform: translateY(-4px); }
  .who-groups li:hover { transform: translateY(-3px); }
}

/* ---- reduced motion: everything shows in its final state, nothing loops ---- */
@media (prefers-reduced-motion: reduce) {
  .flowline, .hero-shape .ring-sway, .hero-shape .dot-drift { animation: none !important; }
  .hoptrack-pulse { display: none; }
  [data-pulse="1"] .hoptrack-circle, .check-card.is-busy .check-form::after, .check-result .findings > li, .hoppanel-card { animation: none !important; }
  .sec-tick path { stroke-dashoffset: 0; animation: none !important; }
  .promise-list .promise { opacity: 1; }
  .watch-item:hover, .who-groups li:hover { transform: none; }
}

