const path = require("path");
const fs = require("fs");
const pwPath = process.env.PW || path.resolve(__dirname, "../../../../../../../../Downloads/LaunchWitness/e2e/node_modules/playwright-core");
const { chromium } = require(pwPath);

const base = process.argv[2] || "http://localhost:8000";
const label = process.argv[3] || "run";
const headless = process.argv.includes("--headless");
const shotsIdx = process.argv.indexOf("--shots");
const shots = shotsIdx > 0 ? process.argv[shotsIdx + 1] : null;

const INIT = `
(() => {
  const w = window;
  w.__perf = { frames: [], longtasks: [], cls: 0, commits: 0, recording: false };
  w.__REACT_DEVTOOLS_GLOBAL_HOOK__ = {
    supportsFiber: true, renderers: new Map(), inject() { return 1; },
    onCommitFiberRoot() { w.__perf.commits++; }, onCommitFiberUnmount() {}, onPostCommitFiberRoot() {},
    checkDCE() {}, onScheduleFiberRoot() {}, isDisabled: false,
  };
  try {
    new PerformanceObserver((l) => { for (const e of l.getEntries()) w.__perf.longtasks.push({ t: e.startTime, d: e.duration }); })
      .observe({ type: "longtask", buffered: true });
    new PerformanceObserver((l) => { for (const e of l.getEntries()) if (!e.hadRecentInput) w.__perf.cls += e.value; })
      .observe({ type: "layout-shift", buffered: true });
  } catch (e) {}
  let last = 0;
  const tick = (t) => { if (w.__perf.recording && last) w.__perf.frames.push(t - last); last = t; requestAnimationFrame(tick); };
  requestAnimationFrame(tick);
})();`;

const CATS = ["devtools.timeline", "disabled-by-default-devtools.timeline", "disabled-by-default-devtools.timeline.frame", "v8.execute", "blink.user_timing"].join(",");
const SCRIPT = new Set(["FunctionCall", "EvaluateScript", "v8.compile", "TimerFire", "FireAnimationFrame", "EventDispatch", "RunMicrotasks", "v8.evaluateModule", "MajorGC", "MinorGC", "V8.GC_SCAVENGER"]);
const RENDER = new Set(["Layout", "UpdateLayoutTree", "RecalculateStyles", "PrePaint", "Layerize", "UpdateLayer", "HitTest", "ScheduleStyleRecalculation", "IntersectionObserverController::computeIntersections", "SVGAnimation", "Animation"]);
const PAINT = new Set(["Paint", "PaintImage", "RasterTask", "CompositeLayers", "Decode Image", "GPUTask", "UpdateLayerTree", "Commit", "Rasterize"]);

async function trace(cdp, fn) {
  const events = [];
  const onData = (d) => events.push(...d.value);
  cdp.on("Tracing.dataCollected", onData);
  await cdp.send("Tracing.start", { categories: CATS, transferMode: "ReportEvents" });
  await cdp.send("Profiler.enable");
  await cdp.send("Profiler.setSamplingInterval", { interval: 200 });
  await cdp.send("Profiler.start");
  await fn();
  const { profile } = await cdp.send("Profiler.stop");
  const done = new Promise((r) => cdp.once("Tracing.tracingComplete", r));
  await cdp.send("Tracing.end");
  await done;
  cdp.off("Tracing.dataCollected", onData);
  return { events, profile };
}

function summarise(events, profile) {
  // only the renderer main thread (CrRendererMain) + compositor/raster for painting
  const threads = {};
  for (const e of events) if (e.ph === "M" && e.name === "thread_name") threads[`${e.pid}:${e.tid}`] = e.args.name;
  const isMain = (e) => threads[`${e.pid}:${e.tid}`] === "CrRendererMain";
  let scripting = 0, rendering = 0, painting = 0, paintCount = 0;
  const byName = {};
  const paintByFrame = {};
  for (const e of events) {
    if (e.ph !== "X" || !e.dur) continue;
    const ms = e.dur / 1000;
    const main = isMain(e);
    if (main && SCRIPT.has(e.name)) scripting += ms;
    else if (main && RENDER.has(e.name)) rendering += ms;
    else if (PAINT.has(e.name)) { painting += ms; if (e.name === "Paint") paintCount++; }
    if (main) byName[e.name] = (byName[e.name] || 0) + ms;
    if (e.name === "Paint" && e.args?.data?.clip) {
      const c = e.args.data.clip; // quad: 8 numbers
      const w = Math.abs(c[2] - c[0]), h = Math.abs(c[5] - c[1]);
      const k = `${Math.round(w)}x${Math.round(h)}`;
      paintByFrame[k] = (paintByFrame[k] || 0) + 1;
    }
  }
  // top self-time functions from the CPU profile
  const self = {};
  if (profile) {
    const dt = {};
    for (let i = 0; i < profile.samples.length; i++) dt[profile.samples[i]] = (dt[profile.samples[i]] || 0) + (profile.timeDeltas[i] || 0);
    for (const n of profile.nodes) {
      const cf = n.callFrame;
      const name = cf.functionName || "(anonymous)";
      if (["(idle)", "(program)", "(root)"].includes(name)) continue;
      const k = `${name} ${cf.url ? cf.url.split("/").pop() + ":" + (cf.lineNumber + 1) + ":" + (cf.columnNumber + 1) : ""}`.trim();
      self[k] = (self[k] || 0) + (dt[n.id] || 0) / 1000;
    }
  }
  const top = (o, n) => Object.entries(o).sort((a, b) => b[1] - a[1]).slice(0, n).map(([k, v]) => [k, +v.toFixed(1)]);
  return {
    scripting_ms: +scripting.toFixed(1), rendering_ms: +rendering.toFixed(1), painting_ms: +painting.toFixed(1), paint_events: paintCount,
    top_main_thread_events: top(byName, 8), top_functions_self_ms: top(self, 5), paint_sizes: top(paintByFrame, 5),
  };
}

function frameStats(frames) {
  if (!frames.length) return { frames: 0 };
  const total = frames.reduce((a, b) => a + b, 0);
  return {
    frames: frames.length,
    avg_fps: +(1000 / (total / frames.length)).toFixed(1),
    over16: frames.filter((f) => f > 17.5).length, // 16.7 ms + jitter allowance
    over50: frames.filter((f) => f > 50).length,
    max_ms: +Math.max(...frames).toFixed(1),
    p95_ms: +[...frames].sort((a, b) => a - b)[Math.floor(frames.length * 0.95)].toFixed(1),
  };
}

async function metrics(cdp) {
  const { metrics } = await cdp.send("Performance.getMetrics");
  return Object.fromEntries(metrics.map((m) => [m.name, m.value]));
}

async function scenario(browser, name, vp, throttle, isMobile) {
  const ctx = await browser.newContext({ viewport: vp, deviceScaleFactor: isMobile ? 3 : 1, isMobile: false });
  const page = await ctx.newPage();
  const errors = [];
  page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
  page.on("pageerror", (e) => errors.push(String(e)));
  await page.addInitScript(INIT);
  const cdp = await ctx.newCDPSession(page);
  await cdp.send("Performance.enable");
  if (throttle > 1) await cdp.send("Emulation.setCPUThrottlingRate", { rate: throttle });
  const out = { name, viewport: `${vp.width}x${vp.height}`, cpu_throttle: throttle };

  // 1) load + 3 s idle
  const load = await trace(cdp, async () => {
    await page.goto(base + "/", { waitUntil: "load" });
    await page.evaluate(() => (window.__perf.recording = true));
    await page.waitForTimeout(3000);
  });
  const loadPerf = await page.evaluate(() => { const p = window.__perf; const r = { frames: p.frames, longtasks: p.longtasks, cls: p.cls, commits: p.commits }; p.frames = []; p.commits = 0; return r; });
  out.load = { ...frameStats(loadPerf.frames), ...summarise(load.events, load.profile), long_tasks: loadPerf.longtasks.length, long_tasks_over100: loadPerf.longtasks.filter((l) => l.d > 100).length, longest_task_ms: +Math.max(0, ...loadPerf.longtasks.map((l) => l.d)).toFixed(1), react_commits: loadPerf.commits };
  if (shots) await page.screenshot({ path: path.join(shots, `${label}-${name}-hero.png`) });

  // 2) idle after intro: wait until 5 s after load, then 4 s window with nothing happening
  await page.waitForTimeout(2000);
  await page.evaluate(() => { window.__perf.frames = []; window.__perf.commits = 0; });
  const m0 = await metrics(cdp);
  const idle = await trace(cdp, async () => page.waitForTimeout(4000));
  const m1 = await metrics(cdp);
  const idleCommits = await page.evaluate(() => window.__perf.commits);
  const wall = (m1.Timestamp - m0.Timestamp) * 1000;
  const idleSum = summarise(idle.events, idle.profile);
  out.idle = {
    main_thread_busy_pct: +(((m1.TaskDuration - m0.TaskDuration) * 1000 / wall) * 100).toFixed(1),
    script_ms: +((m1.ScriptDuration - m0.ScriptDuration) * 1000).toFixed(1),
    style_layout_ms: +(((m1.RecalcStyleDuration - m0.RecalcStyleDuration) + (m1.LayoutDuration - m0.LayoutDuration)) * 1000).toFixed(1),
    paint_events: idleSum.paint_events, painting_ms: idleSum.painting_ms, react_commits: idleCommits,
    top_main_thread_events: idleSum.top_main_thread_events.slice(0, 5),
  };

  // 3) mousemove over the hero (desktop): React commits
  if (!isMobile) {
    await page.evaluate(() => { window.__perf.commits = 0; });
    for (let i = 0; i < 60; i++) { await page.mouse.move(300 + i * 15, 200 + (i % 10) * 30); await page.waitForTimeout(30); }
    out.mousemove_react_commits = await page.evaluate(() => window.__perf.commits);
    await page.mouse.move(5, 5);
  }

  // 4) 5 s scroll through the hero (wheel), measuring frames
  const heroH = await page.evaluate(() => document.querySelector(".hero-card")?.getBoundingClientRect().height || innerHeight);
  const dist = Math.round(heroH * 1.3);
  const steps = 100;
  await page.mouse.move(vp.width / 2, vp.height / 2);
  await page.evaluate(() => { window.__perf.frames = []; window.__perf.longtasks = []; window.__perf.commits = 0; });
  const sc = await trace(cdp, async () => {
    for (let i = 0; i < steps; i++) { await page.mouse.wheel(0, dist / steps); await page.waitForTimeout(50); }
  });
  const scPerf = await page.evaluate(() => window.__perf);
  out.scroll = { distance_px: dist, ...frameStats(scPerf.frames), ...summarise(sc.events, sc.profile), long_tasks: scPerf.longtasks.length, long_tasks_over100: scPerf.longtasks.filter((l) => l.d > 100).length, react_commits: scPerf.commits };
  out.cls = +(await page.evaluate(() => window.__perf.cls)).toFixed(4);
  out.console_errors = errors;
  await ctx.close();
  return out;
}

(async () => {
  const exe = process.env.LW_CHROME || undefined;
  const browser = await chromium.launch({ headless, executablePath: exe, args: ["--disable-extensions"] });
  const results = [];
  const only = process.env.ONLY;
  if (!only || only === "desktop") results.push(await scenario(browser, "desktop", { width: 1440, height: 900 }, 1, false));
  if (!only || only === "phone") results.push(await scenario(browser, "phone", { width: 390, height: 844 }, 4, true));
  await browser.close();
  const file = path.join(__dirname, `result-${label}.json`);
  fs.writeFileSync(file, JSON.stringify(results, null, 1));
  console.log(JSON.stringify(results, null, 1));
})().catch((e) => { console.error(e); process.exit(1); });

