content.content:
@import "./tokens.css";

/* ================= base ================= */
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
html, body { margin: 0; background: var(--ink); }
body {
  font-family: var(--font);
  font-size: var(--fs-base);
  line-height: var(--lh-body);
  color: var(--text);
  overflow-x: clip; /* marquee overflow; `clip` keeps position: sticky working */
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
h1, h2, h3 { font-weight: var(--fw-regular); letter-spacing: var(--tracking-tight); line-height: var(--lh-snug); }
h1 { margin: 0 0 var(--s-3); font-size: var(--fs-2xl); font-weight: var(--fw-light); line-height: 1.08; }
h2 { font-size: var(--fs-lg); margin: var(--s-7) 0 var(--s-3); }
p { margin: 0 0 var(--s-3); }
a { color: inherit; text-underline-offset: 3px; text-decoration-thickness: 1px; }
.muted { color: var(--muted); }
.small { font-size: var(--fs-sm); }
.mono { font-family: var(--font-mono); font-size: var(--fs-sm); word-break: break-all; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.hp { position: absolute; left: -9999px; width: 1px; height: 1px; overflow: hidden; }
::selection { background: var(--accent); color: var(--accent-ink); }
:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; border-radius: 6px; }
.on-dark :focus-visible { outline-color: var(--accent); }

/* ================= frame + top bar (dark frame, light notch tab) ================= */
}
.pill-cta:hover { transform: translateY(-1px); }
@media (max-width: 760px) {
  .topbar { grid-template-columns: 1fr auto; }
  .notch { display: none; }
}

/* the cream sheet that holds the app screens */
.sheet {
  flex: 1; position: relative; background: var(--bg-gradient); border-radius: var(--r-xl);
  display: flex; flex-direction: column;
}
.with-notch .sheet { border-top-left-radius: var(--r-xl); }
.page { width: 100%; max-width: 48rem; margin: 0 auto; padding: clamp(2rem, 5vw, 4.5rem) var(--gutter) var(--s-7); flex: 1; }

/* ================= buttons + links ================= */
9:  --ink: #161614; /* near-black: dark sections, the frame, primary text */
12:  --on-ink: #f3eee4; /* text on dark */
20:  --accent-ink: #1d2205;
71:  --r-xl: clamp(24px, 3vw, 40px);
  --warning: #b7790c;
  --warning-soft: #fbf0d7;
  --danger: #c0402b;
  --danger-soft: #fbe7e2;

  --bg-gradient: radial-gradient(120% 80% at 85% 0%, var(--cream-glow) 0%, rgba(249, 217, 191, 0) 55%),
    radial-gradient(90% 70% at 0% 100%, #f2e8c9 0%, rgba(242, 232, 201, 0) 60%),
    linear-gradient(180deg, var(--cream) 0%, var(--cream-2) 100%);

  /* type */
  --font: "Inter Tight", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

