toolUseResult.originalFile:
/* S19: landing-page motion. Only transform/opacity animate (plus tiny SVG strokes). Colours are the existing tokens.
   Every effect has a prefers-reduced-motion fallback at the bottom: final state at once, nothing loops. */

/* ---- hero: flowing light-lines (behind everything, inside the clipped hero card) ---- */
.flowlines { position: absolute; inset: 0; z-index: 0; pointer-events: none; overflow: hidden; }
.flowline { position: absolute; inset: 0; width: 100%; height: 100%; will-change: transform, opacity; }
.hero-inner { z-index: 1; }
.fl-a { animation: fl-drift-a 26s var(--ease-in-out) infinite alternate; }
.fl-b { animation: fl-drift-b 32s var(--ease-in-out) infinite alternate; }
.fl-c { animation: fl-drift-b 30s var(--ease-in-out) infinite alternate-reverse, fl-shimmer 9s ease-in-out infinite; }
.fl-d { animation: fl-drift-a 36s var(--ease-in-out) infinite alternate-reverse, fl-shimmer 12s ease-in-out infinite -4s; }
@keyframes fl-drift-a { from { transform: translate3d(-2%, 1.5%, 0) scale(1.02); } to { transform: translate3d(2%, -1.5%, 0) scale(1.06); } }
@keyframes fl-drift-b { from { transform: translate3d(2%, -1%, 0) scale(1.05); } to { transform: translate3d(-2.5%, 2%, 0) scale(1.01); } }
@keyframes fl-shimmer { 0%, 100% { opacity: 0.55; } 50% { opacity: 1; } }
.flowlines[data-paused="1"] .flowline { animation-play-state: paused; }

/* ---- hero stack: tilt wrapper, ring and small dot motion ---- */
.shape-tilt { position: absolute; inset: 0; will-change: transform; transform-style: preserve-3d; }
.hero-shape .ring-sway { animation: ring-sway 12s ease-in-out infinite; transform-origin: 50% 9%; }
@keyframes ring-sway { 0%, 100% { transform: rotate(-2.5deg) scaleX(1); } 50% { transform: rotate(2.5deg) scaleX(0.93); } }
.hero-shape .dot-drift { animation: dot-drift 8s ease-in-out infinite; }
@keyframes dot-drift { 0%, 100% { transform: translate(0, 0); } 33% { transform: translate(7px, -9px); } 66% { transform: translate(-3px, 8px); } }
.hero-card { will-change: transform, border-radius; }

/* ---- dark panels: rounded top edge that flattens as the panel reaches the top ---- */
.panel-cap {
  position: absolute; left: 0; right: 0; top: 0; height: var(--r-xl); pointer-events: none; transform-origin: 50% 0;
  border-top: 1px solid var(--ink-line); border-radius: var(--r-xl) var(--r-xl) 0 0; will-change: transform;
}
.dark-cont { position: relative; }

/* ---- proof: a glow travels hop 01 -> 06 when the section first appears ---- */
.hoptrack-pulse { position: absolute; top: calc(var(--circle) / 2); left: calc(100% / 12); width: calc(100% * 10 / 12); height: 0; pointer-events: none; z-index: 2; opacity: 0; }
.hoptrack-pulse span {
  position: absolute; left: 0; top: 0; width: 70px; height: 70px; margin: -35px 0 0 -35px; border-radius: 50%;
  background: radial-gradient(circle, rgba(251, 255, 224, 0.95) 0, rgba(220, 240, 106, 0.55) 22%, rgba(220, 240, 106, 0) 68%);
}
[data-pulse="1"] .hoptrack-pulse { animation: hop-pulse-x 2.2s linear 0.15s 1 both; }
@keyframes hop-pulse-x { 0% { transform: translateX(0); opacity: 0; } 8% { opacity: 1; } 92% { opacity: 1; } 100% { transform: translateX(100%); opacity: 0; } }
[data-pulse="1"] .hoptrack-circle { animation: hop-node 0.9s var(--ease) both; animation-delay: calc(0.15s + var(--i) * 0.44s); }
@keyframes hop-node {
  0% { transform: scale(1); border-color: var(--ink-line); }
  35% { transform: scale(1.14); border-color: var(--accent); }
  100% { transform: scale(1); border-color: var(--ink-line); }
}
[data-pulse="1"] .hoptrack-hop.open .hoptrack-circle { animation: none; }
.hoppanel-card { animation: hop-panel-in 0.45s var(--ease) both; }
@keyframes hop-panel-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
@media (max-width: 719px) {
  .hoptrack-pulse { left: calc(var(--circle) / 2); width: 0; top: calc(var(--row) / 2); height: calc(100% - var(--row)); }
  [data-pulse="1"] .hoptrack-pulse { animation-name: hop-pulse-y; }
}
@keyframes hop-pulse-y { 0% { transform: translateY(0); opacity: 0; } 8% { opacity: 1; } 92% { opacity: 1; } 100% { transform: translateY(100%); opacity: 0; } }

/* ---- promises: list + beam ---- */
.promise-stage { position: relative; display: grid; gap: var(--s-3); }
.promise-list { list-style: none; margin: 0; padding: 0; display: grid; gap: var(--s-3); }
.promise-list .promise { transition: opacity var(--t-med) var(--ease), transform var(--t-med) var(--ease); opacity: 0.5; padding: var(--s-3) 0 var(--s-4); display: grid; gap: var(--s-2); }
.promise-list .promise.is-active { opacity: 1; }
.promise-list .promise .title { font-size: var(--fs-md); font-weight: var(--fw-medium); display: flex; align-items: center; gap: 0.6rem; }
.promise-list .promise .title::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--accent); flex: none; transition: transform var(--t-med) var(--ease); }
.promise-list .promise.is-active .title::before { transform: scale(1.5); }
.promise-list .promise p { color: var(--on-ink-muted); margin: 0; font-size: var(--fs-sm); }
@media (min-width: 900px) {
  .promise-stage[data-beam="1"] { grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); align-items: stretch; column-gap: var(--s-6); }
  .promise-stage[data-beam="1"] .promise-list { grid-auto-rows: 1fr; gap: 0; }
  .promise-stage[data-beam="1"] .promise { align-content: center; border-top: 1px solid var(--ink-line); padding: var(--s-4) 0; }
  .promise-stage[data-beam="1"] .promise:last-child { border-bottom: 1px solid var(--ink-line); }
  .promise-beam { position: relative; overflow: hidden; border-radius: var(--r-lg); }
