  if (calm || !fine.current || e.pointerType !== "mouse") return;
  const b = e.currentTarget.getBoundingClientRect();
  tiltY.set(((e.clientX - b.left) / b.width - 0.5) * 12);
  tiltX.set(-((e.clientY - b.top) / b.height - 0.5) * 12);
};
const onLeave = () => {
  tiltX.set(0);
  tiltY.set(0);
};

