// node freeze.js <url> <outprefix> [reduce]  → screenshots with every loop frozen at t=6.5 s, at scroll 0 / 35% / 80% of the hero
const { chromium } = require(process.env.PW);
const [url, out, reduce] = process.argv.slice(2);
(async () => {
  const b = await chromium.launch({ headless: true, executablePath: process.env.LW_CHROME });
  for (const [w, h] of [[1440, 900], [390, 844]]) {
    const ctx = await b.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: 1, ignoreHTTPSErrors: true, reducedMotion: reduce ? "reduce" : "no-preference" });
    const p = await ctx.newPage();
    const errs = []; p.on("console", m => m.type() === "error" && errs.push(m.text())); p.on("pageerror", e => errs.push(String(e)));
    await p.goto(url + "/", { waitUntil: "load" });
    await p.waitForTimeout(4500);
    for (const frac of [0, 0.35, 0.8]) {
      await p.evaluate((f) => window.scrollTo(0, Math.round(document.querySelector(".hero-card").offsetHeight * f)), frac);
      await p.waitForTimeout(1500);
      await p.evaluate(() => {
        document.querySelectorAll("svg").forEach(s => { try { s.pauseAnimations(); s.setCurrentTime(6.5); } catch {} });
        document.getAnimations().forEach(a => { try { a.pause(); a.currentTime = 6500; } catch {} });
      });
      await p.waitForTimeout(300);
      await p.screenshot({ path: `${out}-${w}-s${Math.round(frac * 100)}.png` });
      await p.evaluate(() => document.getAnimations().forEach(a => a.play()));
      await p.evaluate(() => document.querySelectorAll("svg").forEach(s => { try { s.unpauseAnimations(); } catch {} }));
    }
    if (errs.length) console.log(w, "errors:", errs);
    await ctx.close();
  }
  await b.close();
})();
EOF
