const scen = `async function scenario(browser, name, vp, throttle, isMobile) {
  const out = { name, viewport: \`\${vp.width}x\${vp.height}\`, cpu_throttle: throttle };
  const open = async () => {
    const ctx = await browser.newContext({ viewport: vp, deviceScaleFactor: isMobile ? 3 : 1 });
    const page = await ctx.newPage();
    const errors = [];
    page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
    page.on("pageerror", (e) => errors.push(String(e)));
    await page.addInitScript(INIT);
    const cdp = await ctx.newCDPSession(page);
    await cdp.send("Performance.enable");
    if (throttle > 1) await cdp.send("Emulation.setCPUThrottlingRate", { rate: throttle });
    return { ctx, page, cdp, errors };
  };
  const heroDist = async (page) => Math.round((await page.evaluate(() => document.querySelector(".hero-card")?.getBoundingClientRect().height || innerHeight)) * 1.3);
  const doScroll = async (page, dist) => { for (let i = 0; i < 100; i++) { await page.mouse.wheel(0, dist / 100); await page.waitForTimeout(50); } };

  // ---- pass A: untraced (frames, long tasks, idle CPU, CLS, React commits) ----
  {
    const { ctx, page, cdp, errors } = await open();
    await page.goto(base + "/", { waitUntil: "load" });
    const loadEnd = await page.evaluate(() => performance.timing.loadEventEnd - performance.timing.navigationStart);
    await page.waitForTimeout(3000);
    const L = await page.evaluate(() => { const p = window.__perf; p.stop(); return { frames: p.frames, longtasks: p.longtasks, commits: p.commits }; });
    const after = L.longtasks.filter((l) => l.t >= loadEnd);
    out.load = { ...frameStats(L.frames), long_tasks: L.longtasks.length, long_tasks_over100: L.longtasks.filter((l) => l.d > 100).length,
      longest_task_ms: +Math.max(0, ...L.longtasks.map((l) => l.d)).toFixed(1),
      after_load_long_tasks: after.length, after_load_over100: after.filter((l) => l.d > 100).length, after_load_longest_ms: +Math.max(0, ...after.map((l) => l.d)).toFixed(1),
      react_commits: L.commits };
    if (shots) await page.screenshot({ path: path.join(shots, \`\${label}-\${name}-hero.png\`) });
    await page.waitForTimeout(2000); // intro done (~5 s after load)
    await page.evaluate(() => { window.__perf.commits = 0; });
    const m0 = await metrics(cdp); await page.waitForTimeout(5000); const m1 = await metrics(cdp);
    const wall = (m1.Timestamp - m0.Timestamp) * 1000;
    out.idle = { main_thread_busy_pct: +(((m1.TaskDuration - m0.TaskDuration) * 1000 / wall) * 100).toFixed(1),
      script_ms: +((m1.ScriptDuration - m0.ScriptDuration) * 1000).toFixed(1),
      style_layout_ms: +(((m1.RecalcStyleDuration - m0.RecalcStyleDuration) + (m1.LayoutDuration - m0.LayoutDuration)) * 1000).toFixed(1),
      react_commits: await page.evaluate(() => window.__perf.commits) };
    if (!isMobile) {
      await page.evaluate(() => { window.__perf.commits = 0; });
      for (let i = 0; i < 60; i++) { await page.mouse.move(300 + i * 15, 200 + (i % 10) * 30); await page.waitForTimeout(30); }
      out.mousemove_react_commits = await page.evaluate(() => window.__perf.commits);
    }
    const dist = await heroDist(page);
    await page.mouse.move(vp.width / 2, vp.height / 2);
    await page.evaluate(() => { const p = window.__perf; p.frames = []; p.longtasks = []; p.commits = 0; p.start(); });
    await doScroll(page, dist);
    const SC = await page.evaluate(() => { const p = window.__perf; p.stop(); return { frames: p.frames, longtasks: p.longtasks, commits: p.commits, cls: p.cls }; });
    out.scroll = { distance_px: dist, ...frameStats(SC.frames), long_tasks: SC.longtasks.length, long_tasks_over100: SC.longtasks.filter((l) => l.d > 100).length, react_commits: SC.commits };
    // idle while scrolled past the hero (loops should be paused)
    await page.mouse.wheel(0, 3000); await page.waitForTimeout(1500);
    const n0 = await metrics(cdp); await page.waitForTimeout(3000); const n1 = await metrics(cdp);
    out.idle_scrolled_away_busy_pct = +(((n1.TaskDuration - n0.TaskDuration) / (n1.Timestamp - n0.Timestamp)) * 100).toFixed(1);
    out.cls = +SC.cls.toFixed(4);
    out.console_errors = errors;
    await ctx.close();
  }
  // ---- pass B: traced (time breakdown + top functions) ----
  {
    const { ctx, page, cdp } = await open();
    const load = await trace(cdp, async () => { await page.goto(base + "/", { waitUntil: "load" }); await page.waitForTimeout(3000); });
    await page.evaluate(() => window.__perf.stop());
    out.load_trace = summarise(load.events, load.profile);
    await page.waitForTimeout(2000);
    const dist = await heroDist(page);
    await page.mouse.move(vp.width / 2, vp.height / 2);
    const sc = await trace(cdp, () => doScroll(page, dist));
    out.scroll_trace = summarise(sc.events, sc.profile);
    await ctx.close();
  }
  return out;
}

`;
