function Reveal({
  children,
  delay = 0,
  className,
  as = "div",
  repeat = false,
}: {
function SectionHead({ id, title, label, children }: { id: string; title: string; label: string; children?: ReactNode }) {
  const calm = useCalm();
  return (
    <div className="section-head">
      <div className="meta">
        <h2 id={id}>
          {title}
        </h2>
        <span className="label">{label}</span>
      </div>
      <motion.div
        className="rule"
        initial={calm ? false : { scaleX: 0 }}
        whileInView={{ scaleX: 1 }}
        viewport={{ once: true, amount: 1 }}
        transition={{ duration: 1.1, ease: EASE }}
      />
      {children && (
        <p>
          {children}
        </p>
      )}
    </div>
  );
}
function Steps() {
  const [active, setActive] = useState(0);
  const [hoverable, setHoverable] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(hover: hover) and (pointer: fine)");
    setHoverable(mq.matches);
  }, []);
  return (
    <ol className="steps">
      {STEPS.map((s, i) => (
        <Reveal as="li" repeat key={s.title} delay={i * 0.07} className={`step-li${active === i ? " active" : ""}`}>
          <button
            type="button"
            className={`step${active === i ? " active" : ""}`}
            aria-expanded={active === i}
            onClick={() => setActive(i)}
            onFocus={() => setActive(i)}
            onMouseEnter={hoverable ? () => setActive(i) : undefined}
          >
            <span className="label">/0{i + 1}</span>
            {s.icon}
            <span className="step-title">{s.title}</span>
            <span className="step-desc">
              <span>
                <span className="txt">{s.text}</span>
              </span>
            </span>
          </button>
        </Reveal>
      ))}
    </ol>
  );
}

